import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { actions } from '../store';
import { saveDashboard, publishDashboard } from '../services/api';
import CardPalette from './CardPalette';
import DashboardCanvas from './DashboardCanvas';
import ConfigPanel from './ConfigPanel';

export default function Builder({ onBack }) {
  const dispatch = useDispatch();
  const state = useSelector(s => s.builder);
  const tabs = state.config.dashboard.tabs;
  const [activeTab, setActiveTab] = useState(null); // null = no tabs / all
  const [saving, setSaving] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [message, setMessage] = useState(null);

  const handleSave = async () => {
    setSaving(true);
    setMessage(null);
    try {
      await saveDashboard({ id: state.id, name: state.name, description: state.description, config: state.config });
      setMessage({ type: 'success', text: 'Saved!' });
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setSaving(false);
    }
  };

  const handlePublish = async () => {
    setPublishing(true);
    setMessage(null);
    try {
      await saveDashboard({ id: state.id, name: state.name, description: state.description, config: state.config });
      const res = await publishDashboard(state.id);
      dispatch(actions.setStatus('published'));
      setMessage({ type: 'success', text: `Published to Metabase! Dashboard ID: ${res.dashboardId}` });
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setPublishing(false);
    }
  };

  return (
    <div style={styles.root}>
      {/* Top toolbar */}
      <div style={styles.toolbar}>
        <button style={styles.backBtn} onClick={onBack}>← Back</button>
        <div style={styles.titleArea}>
          <input
            style={styles.titleInput}
            value={state.name}
            onChange={e => dispatch(actions.setMeta({ name: e.target.value }))}
          />
          <span style={{ ...styles.statusBadge, background: state.status === 'published' ? '#d3f9d8' : '#fff3bf' }}>
            {state.status}
          </span>
        </div>
        {message && (
          <span style={{ fontSize: 12, color: message.type === 'success' ? '#2f9e44' : '#c92a2a', marginRight: 12 }}>
            {message.text}
          </span>
        )}
        <button style={styles.saveBtn} onClick={handleSave} disabled={saving}>
          {saving ? 'Saving…' : 'Save Draft'}
        </button>
        <button style={styles.publishBtn} onClick={handlePublish} disabled={publishing}>
          {publishing ? 'Publishing…' : '🚀 Publish to Metabase'}
        </button>
      </div>

      {/* Tab bar */}
      {tabs.length > 0 && (
        <div style={styles.tabBar}>
          <button style={{ ...styles.tab, ...(activeTab === null ? styles.activeTab : {}) }} onClick={() => setActiveTab(null)}>
            All
          </button>
          {tabs.map((tab, i) => (
            <button key={i} style={{ ...styles.tab, ...(activeTab === i ? styles.activeTab : {}) }} onClick={() => setActiveTab(i)}>
              {tab.name}
            </button>
          ))}
        </div>
      )}

      {/* Main area */}
      <div style={styles.main}>
        <CardPalette onAdd={card => dispatch(actions.addCard({ ...card, tabIndex: activeTab ?? undefined }))} />
        <DashboardCanvas activeTab={activeTab} />
        <ConfigPanel />
      </div>
    </div>
  );
}

const styles = {
  root: { display: 'flex', flexDirection: 'column', height: '100vh', fontFamily: 'system-ui, sans-serif' },
  toolbar: { display: 'flex', alignItems: 'center', gap: 10, padding: '10px 16px', background: '#fff', borderBottom: '1px solid #dee2e6', flexShrink: 0 },
  backBtn: { padding: '6px 12px', border: '1px solid #dee2e6', borderRadius: 6, background: '#fff', cursor: 'pointer', fontSize: 13 },
  titleArea: { display: 'flex', alignItems: 'center', gap: 8, flex: 1 },
  titleInput: { fontSize: 16, fontWeight: 700, border: 'none', outline: 'none', background: 'transparent', minWidth: 200 },
  statusBadge: { fontSize: 11, padding: '2px 8px', borderRadius: 10, fontWeight: 600 },
  saveBtn: { padding: '8px 16px', border: '1px solid #ced4da', borderRadius: 6, background: '#fff', cursor: 'pointer', fontSize: 13 },
  publishBtn: { padding: '8px 18px', border: 'none', borderRadius: 6, background: '#2f9e44', color: '#fff', cursor: 'pointer', fontWeight: 700, fontSize: 13 },
  tabBar: { display: 'flex', gap: 4, padding: '8px 16px', background: '#f8f9fa', borderBottom: '1px solid #dee2e6' },
  tab: { padding: '5px 14px', border: '1px solid #dee2e6', borderRadius: 20, background: '#fff', cursor: 'pointer', fontSize: 12 },
  activeTab: { background: '#4c6ef5', color: '#fff', borderColor: '#4c6ef5' },
  main: { display: 'flex', flex: 1, overflow: 'hidden' },
};
